import re


_DECIMAL = re.compile(r"^[+-]?[0-9]+$")


def _failure(code):
    return {"ok": False, "config": {}, "error": code}


def _matches_type(value, expected):
    if expected == "boolean":
        return type(value) is bool
    if expected == "integer":
        return type(value) is int
    if expected == "string":
        return type(value) is str
    if expected == "number":
        return type(value) in (int, float)
    if expected == "object":
        return type(value) is dict
    if expected == "array":
        return type(value) is list
    if expected == "null":
        return value is None
    return False


def _parse_environment(value, expected):
    if type(value) is not str:
        raise ValueError
    if expected == "boolean":
        if value == "true":
            return True
        if value == "false":
            return False
        raise ValueError
    if expected == "integer":
        if not _DECIMAL.fullmatch(value):
            raise ValueError
        return int(value, 10)
    if expected == "string":
        return value
    raise ValueError


def evaluate(request, policy):
    defaults = policy.get("defaults", {})
    types = policy.get("types", {})
    config = dict(defaults)
    known = set(defaults)

    for layer in request.get("layers", []):
        for key, value in layer.items():
            if key not in known:
                return _failure("unknown_key")
            if value is None and policy.get("null_resets") is True:
                config[key] = defaults[key]
            else:
                config[key] = value

    environment = request.get("environment", {})
    if environment:
        if policy.get("environment") is not True:
            return _failure("environment")
        for key, value in environment.items():
            if key not in known:
                return _failure("unknown_key")
            try:
                config[key] = _parse_environment(value, types.get(key))
            except (TypeError, ValueError):
                return _failure("environment")

    for key, value in config.items():
        if key not in types or not _matches_type(value, types[key]):
            return _failure("type")

    return {"ok": True, "config": config, "error": None}

